{
  "items": [
    {
      "name": "iSup",
      "module_name": "Mathlib.Order.SetNotation",
      "kind": "definition",
      "type": "{α : Type u} → {ι : Sort v} → [SupSet α] → (ι → α) → α"
    },
    {
      "name": "Seminorm.finset_sup_apply_le",
      "module_name": "Mathlib.Analysis.Seminorm",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_3} {E : Type u_7} {ι : Type u_11} [inst : SeminormedRing 𝕜] [inst_1 : AddCommGroup E]\n  [inst_2 : Module 𝕜 E] {p : ι → Seminorm 𝕜 E} {s : Finset ι} {x : E} {a : ℝ},\n  0 ≤ a → (∀ i ∈ s, (p i) x ≤ a) → (s.sup p) x ≤ a"
    },
    {
      "name": "Polynomial.supDegree_eq_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), AddMonoidAlgebra.supDegree id p.toFinsupp = p.natDegree"
    },
    {
      "name": "AddMonoidAlgebra.supDegree_sum_le",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {B : Type u_5} [inst : Semiring R] [inst_1 : SemilatticeSup B] [inst_2 : OrderBot B]\n  {D : A → B} {ι : Type u_7} {s : Finset ι} {f : ι → AddMonoidAlgebra R A},\n  AddMonoidAlgebra.supDegree D (∑ i ∈ s, f i) ≤ s.sup fun i => AddMonoidAlgebra.supDegree D (f i)"
    },
    {
      "name": "Int.csSup_of_not_bddAbove",
      "module_name": "Mathlib.Data.Int.ConditionallyCompleteOrder",
      "kind": "theorem",
      "type": "∀ {s : Set ℤ}, ¬BddAbove s → sSup s = 0"
    }
  ]
}
